-- CatModLangFor42: MOD text conflict notice, conflict list and ModOptions page.
-- Data: media/CatModLang/conflicts.tsv (K = key with owners of different English, V = MOD rewriting vanilla
-- keys), generated by scripts/build_mod.py. Rules: .claude/skills/modlang-dev/references/variants.md.
-- All text comes from getText (sources/pack_ui.json); no non-ASCII literals here (Kahlua truncates them).

require "ISUI/ISModalRichText"

local lang = tostring(Translator.getLanguage())
if (lang ~= "CH" and lang ~= "CN") or not CatModLang or not CatModLang.activeOwners then return end

local SEEN = "CatModLangFor42_conflicts_seen.txt" -- in Zomboid/Lua/
local NOTICE_PAIRS = 3

-- { rows = { { {g, wid, root}, ... }, ... }, vanilla = { [wid] = { total, covered } } }
function CatModLang.readConflictData()
    local data = { rows = {}, vanilla = {} }
    for _, line in ipairs(CatModLang.readLines("media/CatModLang/conflicts.tsv") or {}) do
        local f = {}
        for s in line:gmatch("[^\t]+") do f[#f + 1] = s end
        if f[1] == "K" then
            local row = {}
            for i = 3, #f do
                local g, wid, root = f[i]:match("^(%d+):([^/]*)/(.+)$")
                if g then
                    row[#row + 1] = { g = g, wid = CatModLang.unescape(wid), root = CatModLang.unescape(root) }
                end
            end
            data.rows[#data.rows + 1] = row
        elseif f[1] == "V" and f[2] then
            data.vanilla[f[2]] = { total = tonumber(f[3]) or 0, covered = tonumber(f[4]) or 0 }
        end
    end
    return data
end

-- Workshop item of a MOD (local copies count as their own item).
local function itemOf(wid, root)
    return wid ~= "" and wid or ("/" .. root)
end

local function modName(m)
    local name = tostring(m.info and m.info:getName() or m.id)
    return (name:gsub("<", "&lt;"):gsub(">", "&gt;"))
end

-- Sorts active owners' conflicts into the three groups of the list.
-- owners/mods as returned by CatModLang.activeOwners(); data from CatModLang.readConflictData().
-- Pair = { early, late (load order; late is shown), count, sig }. Vanilla = { ranks, total, covered }.
function CatModLang.classify(owners, mods, data)
    local pairsByKey, order = {}, {}
    for _, row in ipairs(data.rows) do
        local act = {}
        for _, o in ipairs(row) do
            local rank = CatModLang.ownerRank(owners, o.wid, o.root)
            if rank then act[#act + 1] = { rank = rank, g = o.g } end
        end
        for i = 1, #act - 1 do
            for j = i + 1, #act do
                local a, b = act[i], act[j]
                if a.g ~= b.g and a.rank ~= b.rank then
                    local early, late = math.min(a.rank, b.rank), math.max(a.rank, b.rank)
                    local k = early .. "-" .. late
                    local p = pairsByKey[k]
                    if not p then
                        p = { early = early, late = late, count = 0 }
                        pairsByKey[k] = p
                        order[#order + 1] = p
                    end
                    p.count = p.count + 1
                end
            end
        end
    end

    local items, requires, ranks = {}, {}, {}
    for rank, m in pairs(mods) do
        ranks[#ranks + 1] = rank
        items[rank] = itemOf(m.wid, m.root)
        local req = {}
        local list = m.info and m.info:getRequire()
        for i = 0, (list and list:size() or 0) - 1 do
            local wid, root = CatModLang.ownerOf(getModInfoByID(string.trim(list:get(i))))
            if root then req[itemOf(wid, root)] = true end
        end
        requires[rank] = req
    end

    local res = { overwrite = {}, addon = {}, vanilla = {} }
    for _, p in ipairs(order) do
        local e, l = p.early, p.late
        if items[e] == items[l] or requires[e][items[l]] or requires[l][items[e]] then
            res.addon[#res.addon + 1] = p
        else
            local se = mods[e].wid .. "/" .. mods[e].root
            local sl = mods[l].wid .. "/" .. mods[l].root
            p.sig = se < sl and (se .. "|" .. sl) or (sl .. "|" .. se)
            res.overwrite[#res.overwrite + 1] = p
        end
    end
    local function byCount(a, b)
        if a.count ~= b.count then return a.count > b.count end
        return a.early < b.early or (a.early == b.early and a.late < b.late)
    end
    CatModLang.sortSafe(res.overwrite, byCount)
    CatModLang.sortSafe(res.addon, byCount)

    local sigs = {}
    for i, p in ipairs(res.overwrite) do sigs[i] = p.sig end
    CatModLang.sortSafe(sigs)
    res.signature = table.concat(sigs, ";")

    local byWid = {}
    CatModLang.sortSafe(ranks)
    for _, rank in ipairs(ranks) do
        local m = mods[rank]
        local v = m.wid ~= "" and data.vanilla[m.wid]
        if v and v.total > 0 then
            local e = byWid[m.wid]
            if not e then
                e = { ranks = {}, total = v.total, covered = v.covered }
                byWid[m.wid] = e
                res.vanilla[#res.vanilla + 1] = e
            end
            e.ranks[#e.ranks + 1] = rank
        end
    end
    return res
end

local function current()
    local owners, mods = CatModLang.activeOwners()
    return CatModLang.classify(owners, mods, CatModLang.readConflictData()), mods
end

local function pairLines(mods, p, showing)
    local late = modName(mods[p.late])
    -- same chunk as the name: a colour tag starts a new chunk and the rich text trims the space before it
    if showing then late = late .. " " .. getText("IGUI_CatModLang_Showing") end
    return " <RGB:1,1,1> " .. modName(mods[p.early]) .. " <LINE> <RGB:1,1,1> " .. late
        .. " <LINE> <TEXT> " .. getText("IGUI_CatModLang_Count", p.count) .. " <LINE> <LINE> "
end

function CatModLang.listText(res, mods)
    if #res.overwrite + #res.addon + #res.vanilla == 0 then
        return " <TEXT> " .. getText("IGUI_CatModLang_Empty")
    end
    local t = { " <H1> ", getText("IGUI_CatModLang_ListTitle"), " <LINE> <TEXT> ",
        getText("IGUI_CatModLang_ListIntro"), " <LINE> <LINE> " }
    if #res.overwrite > 0 then
        t[#t + 1] = " <H2> " .. getText("IGUI_CatModLang_GroupOverwrite", #res.overwrite) .. " <LINE> <TEXT> "
            .. getText("IGUI_CatModLang_GroupOverwriteDesc") .. " <LINE> <LINE> "
        for _, p in ipairs(res.overwrite) do t[#t + 1] = pairLines(mods, p, true) end
    end
    if #res.addon > 0 then
        t[#t + 1] = " <H2> " .. getText("IGUI_CatModLang_GroupAddon", #res.addon) .. " <LINE> <TEXT> "
            .. getText("IGUI_CatModLang_GroupAddonDesc") .. " <LINE> <LINE> "
        for _, p in ipairs(res.addon) do
            t[#t + 1] = " <RGB:1,1,1> " .. modName(mods[p.late]) .. " <LINE> <TEXT> "
                .. getText("IGUI_CatModLang_Rewrites", modName(mods[p.early]), p.count) .. " <LINE> <LINE> "
        end
    end
    if #res.vanilla > 0 then
        t[#t + 1] = " <H2> " .. getText("IGUI_CatModLang_GroupVanilla", #res.vanilla) .. " <LINE> <TEXT> "
            .. getText("IGUI_CatModLang_GroupVanillaDesc") .. " <LINE> <LINE> "
        for _, v in ipairs(res.vanilla) do
            local names = {}
            for i, rank in ipairs(v.ranks) do names[i] = modName(mods[rank]) end
            local count = v.covered > 0 and getText("IGUI_CatModLang_VanillaCovered", v.total, v.covered)
                or getText("IGUI_CatModLang_CountAtLeast", v.total)
            t[#t + 1] = " <RGB:1,1,1> " .. table.concat(names, " <LINE> <RGB:1,1,1> ") .. " <LINE> <TEXT> "
                .. count .. " <LINE> <LINE> "
        end
    end
    return table.concat(t)
end

function CatModLang.noticeText(res, mods)
    local n = #res.overwrite
    local t = { " <H1> ", getText("IGUI_CatModLang_NoticeTitle"), " <LINE> <LINE> <TEXT> ",
        getText("IGUI_CatModLang_NoticeBody", n), " <LINE> <LINE> " }
    for i = 1, math.min(n, NOTICE_PAIRS) do t[#t + 1] = pairLines(mods, res.overwrite[i], false) end
    if n > NOTICE_PAIRS then
        t[#t + 1] = " <TEXT> " .. getText("IGUI_CatModLang_NoticeMore", n - NOTICE_PAIRS) .. " <LINE> <LINE> "
    end
    t[#t + 1] = " <TEXT> " .. getText("IGUI_CatModLang_NoticeHint", getText("UI_mainscreen_option"),
        getText("UI_mainscreen_mods"))
    return table.concat(t)
end

-- Modal: vanilla ISModalRichText plus Esc / Enter / arrow keys, B and d-pad for the one-button list.
local Modal = ISModalRichText:derive("CatModLangModal")
local KEYS = { [Keyboard.KEY_ESCAPE] = "close", [Keyboard.KEY_RETURN] = "main",
    [Keyboard.KEY_UP] = -40, [Keyboard.KEY_DOWN] = 40 }

function Modal:scrollBy(d)
    self.chatText:setYScroll(self.chatText:getYScroll() - d)
end

function Modal:isKeyConsumed(key)
    return KEYS[key] ~= nil
end

function Modal:onKeyRelease(key)
    local act = KEYS[key]
    if not act or not self:isVisible() then return end
    if act == "close" then self:onClick(self.no or self.ok)
    elseif act == "main" then self:onClick(self.yes or self.ok)
    else self:scrollBy(act) end
end

function Modal:onJoypadDown(button, joypadData)
    if button == Joypad.BButton and self.ok then return self:onClick(self.ok) end
    ISModalRichText.onJoypadDown(self, button, joypadData)
end

function Modal:onJoypadDirUp() self:scrollBy(-40) end
function Modal:onJoypadDirDown() self:scrollBy(40) end

local function open(kind, text, onclick)
    local core = getCore()
    local w = math.min(kind == "list" and 560 or 480, core:getScreenWidth() - 40)
    local h = 160
    local player = getSpecificPlayer(0) and 0 or nil
    local m = Modal:new(core:getScreenWidth() / 2 - w / 2, core:getScreenHeight() / 2 - h / 2, w, h, text,
        kind == "notice", nil, onclick, player)
    m.yesText, m.noText = "IGUI_CatModLang_ViewList", "IGUI_CatModLang_Close"
    m:initialise()
    if m.no then
        -- Close deletes nothing: plain ISButton look instead of the vanilla cancel red.
        m.no:setBackgroundRGBA(0, 0, 0, 1)
        m.no:setBackgroundColorMouseOverRGBA(0.3, 0.3, 0.3, 1)
        m.no:setBorderRGBA(0.7, 0.7, 0.7, 1)
    else
        m.ok:setTitle(getText("IGUI_CatModLang_Close"))
    end
    m:setWantKeyEvents(true)
    m:addToUIManager()
    m:setAlwaysOnTop(true)
    local joypad = player and JoypadState.players[player + 1]
    if joypad then
        m.prevFocus = joypad.focus
        setJoypadFocus(player, m)
    else
        joypad = JoypadState.getMainMenuJoypad()
        if joypad then
            m.prevFocus = joypad.focus
            joypad.focus = m
            updateJoypadFocus(joypad)
        end
    end
    CatModLang.window = m
    print("[CatModLang] conflicts " .. kind .. " opened")
    return m
end

function CatModLang.openList()
    local res, mods = current()
    return open("list", CatModLang.listText(res, mods))
end

local function lastSeen()
    local r = getFileReader(SEEN, false)
    if not r then return nil end
    local s = r:readLine()
    r:close()
    return s
end

local options = PZAPI.ModOptions:create("CatModLangFor42", "UI_CatModLang_Options")
local notify = options:addTickBox("notify", "UI_CatModLang_NotifyOption", true)
options:addButton("openList", "UI_CatModLang_OpenList", nil, function() CatModLang.openList() end)

-- Opens the notice when the set of MODs overwriting each other differs from the one last seen.
function CatModLang.maybeNotify()
    local res, mods = current()
    local sig = res.signature
    if sig == "" or not notify:getValue() or sig == lastSeen() then return nil end
    return open("notice", CatModLang.noticeText(res, mods), function(_, button)
        local w = getFileWriter(SEEN, true, false)
        if w then
            w:write(sig)
            w:close()
        end
        if button and button.internal == "YES" then CatModLang.openList() end
    end)
end

local function onFirstTick()
    Events.OnTick.Remove(onFirstTick)
    local ok, err = pcall(CatModLang.maybeNotify)
    if not ok then print("[CatModLang] conflicts notice failed: " .. tostring(err)) end
end

Events.OnGameStart.Add(function() Events.OnTick.Add(onFirstTick) end)
